    { family: "Poppins", style: "Bold" },
    { family: "Andika", style: "Regular" }
  ];
  for (const font of fonts) {
    try {
      await figma.loadFontAsync(font);
    } catch (e) {
      console.log('Font load warning:', font, e);
    }
  }

  // Find asset component helper
  function findComponent(name) {
    for (const page of figma.root.children) {
      const comp = page.findOne(node => node.name === name && (node.type === 'COMPONENT' || node.type === 'COMPONENT_SET'));
      if (comp) return comp;
    }
    return null;
  }

  // Helper to clone / instantiate or place symbol
  function createAssetInstance(name, width, height) {
    const comp = findComponent(name);
    if (comp) {
      if (comp.type === 'COMPONENT') {
        const inst = comp.createInstance();
        if (width && height) {
          inst.resize(width, height);
        }
        return inst;
      }
    }
    // Fallback placeholder frame if component not found directly as COMPONENT
    const frame = figma.createFrame();
    frame.name = name;
    frame.resize(width || 40, height || 40);
    frame.fills = [{ type: 'SOLID', color: { r: 0.9, g: 0.9, b: 0.9 } }];
    return frame;
  }

