    { from: '16_Partners', target: '07_Home', nodeName: 'Tab_Home' },
    { from: '16_Partners', target: '15_Itinerary_Form', nodeName: 'Tab_Guide' },
    { from: '17_Social_Links', target: '18_Profile', nodeName: 'Icon_Back' },
