    { from: '18_Profile', target: '16_Partners', nodeName: 'Button_Save_Settings' }
  ];

  let count = 0;
  for (const rule of linkRules) {
    const srcFrame = frames[rule.from];
    const destFrame = frames[rule.target];
    if (!srcFrame || !destFrame) continue;

    let triggerNode = srcFrame;
    if (rule.nodeName !== rule.from) {
      triggerNode = srcFrame.findOne(n => n.name === rule.nodeName) || srcFrame;
    }

    try {
      if (rule.timeout) {
        triggerNode.reactions = [{
          action: { type: 'NODE', destinationId: destFrame.id, navigation: 'NAVIGATE' },
          trigger: { type: 'AFTER_TIMEOUT', timeout: 1 }
        }];
      } else {
        triggerNode.reactions = [{
          action: { type: 'NODE', destinationId: destFrame.id, navigation: 'NAVIGATE' },
          trigger: { type: 'ON_CLICK' }
        }];
      }
      count++;
    } catch (e) {
      console.log('Link error:', rule, e);
    }
  }

  return `Successfully connected ${count} prototype links across 18 frames!`;
})()
